"""Regular-language objects and the restricted pattern grammar.

The toolkit owns its own matcher: the documented pattern grammar has no dot
wildcard, no anchors, no `+`/`?`, no negated classes and no numeric escapes,
and matching runs over Latin-1 code points where ASCII ranges never accept a
byte above 127.  Python's `re` module therefore cannot be used directly.

Two layers live here.  The `Regex` object hierarchy is the classic AST used by
model authors; `Pattern` parses the wire pattern syntax and compiles it into a
bitmask NFA that answers full-string membership queries.
"""
from .errors import InvalidCampaign


class Regex(object):
    """A regular expression."""


class Empty(Regex):
    """Matches the empty string."""

    def __str__(self) -> str:
        return ""


class Range(Regex):
    """Matches a single character inside an inclusive code point range."""

    def __init__(self, low: str, high: str):
        if len(low) != 1 or len(high) != 1:
            raise ValueError("Range must be single characters")
        self.low = low
        self.high = high

    def __str__(self) -> str:
        return f"[{self.low}-{self.high}]"


class Choice(Regex):
    """Matches any one of several alternatives."""

    def __init__(self, *args):
        if len(args) < 2:
            raise ValueError("Choice must have at least two expressions")
        self.exprs = args

    def __str__(self) -> str:
        return "(" + "|".join(str(e) for e in self.exprs) + ")"


class Seq(Regex):
    """Matches a sequence of expressions."""

    def __init__(self, *args):
        if len(args) < 2:
            raise ValueError("Seq must have at least two expressions")
        self.exprs = args

    def __str__(self) -> str:
        return "(" + "".join(str(e) for e in self.exprs) + ")"


class Star(Regex):
    """Matches zero or more iterations of an expression."""

    def __init__(self, r: Regex):
        self.expr = r

    def __str__(self) -> str:
        return f"({str(self.expr)})*"


def chars(low: str, high: str) -> Regex:
    return Range(low, high)


def text(s: str) -> Regex:
    if s == "":
        return empty()
    if len(s) == 1:
        return chars(s, s)
    return seq(*[chars(c, c) for c in s])


def choice(*args) -> Regex:
    return Choice(*args)


def seq(*args) -> Regex:
    return Seq(*args)


def star(r: Regex) -> Regex:
    return Star(r)


def plus(r: Regex) -> Regex:
    return seq(r, star(r))


def empty() -> Regex:
    return Empty()


# --------------------------------------------------------------------------
# Pattern grammar: union of sequences, sequences of atoms, postfix stars.
# --------------------------------------------------------------------------

_SPECIAL = "()[]|*\\"
_CLASS_SPECIAL = "]\\-"


def _parse(source: str) -> Regex:
    """Parse the documented pattern grammar into a `Regex` AST."""
    if not isinstance(source, str):
        raise InvalidCampaign("pattern must be a string")
    pos = 0
    limit = len(source)

    def peek(offset=0):
        index = pos + offset
        return source[index] if index < limit else None

    def union():
        nonlocal pos
        alternatives = [sequence()]
        while peek() == "|":
            pos += 1
            alternatives.append(sequence())
        if len(alternatives) == 1:
            return alternatives[0]
        return Choice(*alternatives)

    def sequence():
        items = []
        while True:
            char = peek()
            if char is None or char == "|" or char == ")":
                break
            items.append(item())
        if not items:
            return Empty()
        if len(items) == 1:
            return items[0]
        return Seq(*items)

    def item():
        nonlocal pos
        atom = parse_atom()
        while peek() == "*":
            pos += 1
            atom = star(atom)
        return atom

    def parse_atom():
        nonlocal pos
        char = peek()
        if char is None:
            raise InvalidCampaign("pattern ends unexpectedly")
        if char == "(":
            pos += 1
            inner = union()
            if peek() != ")":
                raise InvalidCampaign("unbalanced parenthesis")
            pos += 1
            return inner
        if char == "[":
            pos += 1
            return char_class()
        if char == "\\":
            pos += 1
            nxt = peek()
            if nxt is None:
                raise InvalidCampaign("dangling escape")
            pos += 1
            return chars(nxt, nxt)
        if char in "*":
            raise InvalidCampaign("stray repetition")
        pos += 1
        return chars(char, char)

    def literal_in_class():
        nonlocal pos
        char = peek()
        if char is None:
            raise InvalidCampaign("unterminated class")
        if char == "\\":
            pos += 1
            nxt = peek()
            if nxt is None:
                raise InvalidCampaign("dangling escape")
            pos += 1
            return nxt
        pos += 1
        return char

    def char_class():
        nonlocal pos
        parts = []
        while True:
            char = peek()
            if char is None:
                raise InvalidCampaign("unterminated class")
            if char == "]":
                pos += 1
                break
            low = literal_in_class()
            if peek() == "-" and peek(1) is not None and peek(1) != "]":
                pos += 1
                high = literal_in_class()
            else:
                high = low
            if ord(low) > ord(high):
                raise InvalidCampaign("descending class range")
            parts.append((low, high))
        if not parts:
            raise InvalidCampaign("empty character class")
        if len(parts) == 1:
            return chars(parts[0][0], parts[0][1])
        return Choice(*[chars(low, high) for low, high in parts])

    result = union()
    if pos != limit:
        raise InvalidCampaign("unconsumed pattern input")
    return result


class _Nfa(object):
    """A bitmask NFA over Latin-1 code points."""

    __slots__ = ("start", "accept", "closure", "table")

    def __init__(self, regex: Regex):
        eps = []
        trans = []

        def new_state():
            eps.append([])
            trans.append([])
            return len(eps) - 1

        def frag(node):
            if isinstance(node, Empty):
                start = new_state()
                end = new_state()
                eps[start].append(end)
                return start, end
            if isinstance(node, Range):
                start = new_state()
                end = new_state()
                trans[start].append(((ord(node.low), ord(node.high)), end))
                return start, end
            if isinstance(node, Choice):
                start = new_state()
                end = new_state()
                for sub in node.exprs:
                    a, b = frag(sub)
                    eps[start].append(a)
                    eps[b].append(end)
                return start, end
            if isinstance(node, Seq):
                first_start, previous = frag(node.exprs[0])
                for sub in node.exprs[1:]:
                    a, b = frag(sub)
                    eps[previous].append(a)
                    previous = b
                return first_start, previous
            if isinstance(node, Star):
                start = new_state()
                end = new_state()
                a, b = frag(node.expr)
                eps[start].append(a)
                eps[start].append(end)
                eps[b].append(a)
                eps[b].append(end)
                return start, end
            raise InvalidCampaign("unsupported regex node")

        start, accept = frag(_normalize(regex))
        self.start = start
        self.accept = accept
        count = len(eps)
        closure = []
        for state in range(count):
            seen = 1 << state
            stack = [state]
            while stack:
                node = stack.pop()
                for nxt in eps[node]:
                    bit = 1 << nxt
                    if not seen & bit:
                        seen |= bit
                        stack.append(nxt)
            closure.append(seen)
        self.closure = closure
        table = []
        for state in range(count):
            row = [0] * 256
            for ranges, target in trans[state]:
                bit = 1 << target
                for code in ranges:
                    low, high = code
                    if low > 255:
                        continue
                    top = high if high < 255 else 255
                    for value in range(low, top + 1):
                        row[value] |= bit
            table.append(row)
        self.table = table

    def matches(self, string: str) -> bool:
        current = self.closure[self.start]
        table = self.table
        closure = self.closure
        for char in string:
            code = ord(char)
            if code > 255:
                return False
            nxt = 0
            mask = current
            while mask:
                low = mask & -mask
                state = low.bit_length() - 1
                mask ^= low
                nxt |= table[state][code]
            if not nxt:
                return False
            current = 0
            mask = nxt
            while mask:
                low = mask & -mask
                state = low.bit_length() - 1
                mask ^= low
                current |= closure[state]
        return (current >> self.accept) & 1 == 1


def _normalize(regex: Regex) -> Regex:
    """Collapse single-element sequences/choices so `frag` stays simple."""
    if isinstance(regex, Seq):
        if not regex.exprs:
            return Empty()
        if len(regex.exprs) == 1:
            return _normalize(regex.exprs[0])
        return Seq(*[_normalize(item) for item in regex.exprs])
    if isinstance(regex, Choice):
        if not regex.exprs:
            raise InvalidCampaign("empty union")
        if len(regex.exprs) == 1:
            return _normalize(regex.exprs[0])
        return Choice(*[_normalize(item) for item in regex.exprs])
    if isinstance(regex, Star):
        return Star(_normalize(regex.expr))
    return regex


_CACHE = {}


class Pattern(object):
    """A compiled wire pattern; answers full-string membership queries."""

    __slots__ = ("source", "_nfa")

    def __init__(self, source: str):
        self.source = source
        self._nfa = _Nfa(_parse(source))

    def matches(self, string: str) -> bool:
        if not isinstance(string, str):
            return False
        return self._nfa.matches(string)

    def __repr__(self) -> str:
        return f"Pattern({self.source!r})"


def compile_pattern(source: str) -> Pattern:
    """Compile a wire pattern, caching by source text."""
    pattern = _CACHE.get(source)
    if pattern is None:
        pattern = Pattern(source)
        _CACHE[source] = pattern
    return pattern


def ismatch(r: Regex, s: str) -> bool:
    """Match a classic `Regex` AST object against a full string."""
    return _Nfa(r).matches(s)
